sp_widget.client_script:
function($scope, spUtil, $timeout) {
  var c = this;
  try { document.body.style.setProperty('background', '#f1f3f5', 'important'); } catch (e) {}
  try { document.body.style.setProperty('margin', '0', 'important'); } catch (e) {}
  /* I63: framed embed never scrolls itself - the frame self-sizes, so the
     inner scrollbar was pure rounding noise (the dark-grey bar). */
  try {
    if (window.frameElement) {
      document.documentElement.style.setProperty('overflow', 'hidden', 'important');
      document.body.style.setProperty('overflow', 'hidden', 'important');
    }
  } catch (e) {}

  function syncFrame() {
    try {
      var fe = window.frameElement;
      if (!fe) { return; }
      fe.style.setProperty('border', '0', 'important');
      fe.style.setProperty('box-shadow', 'none', 'important');
      fe.style.setProperty('width', '100%', 'important');
      fe.style.setProperty('overflow', 'hidden', 'important');
      try { fe.setAttribute('scrolling', 'no'); } catch (e2) {}
      /* I61: measure the widget ROOT, not body.scrollHeight - body can never
         report smaller than the iframe viewport, so the old measure RATCHETED:
         the frame grew with the drill but never shrank back, leaving the outer
         page with a stale, cut-off scroll extent. The root's rect is
         viewport-independent, so the frame recovers when panels close. */
      var root = document.querySelector('.pt-cc');
      if (!root) { return; }
      var h = Math.max(Math.ceil(root.getBoundingClientRect().height) + 2, 640);
      if (fe.__ptH === undefined || Math.abs(fe.__ptH - h) > 4) {
        fe.__ptH = h;
        fe.style.setProperty('height', h + 'px', 'important');
      }
      if (document.documentElement.scrollTop) { document.documentElement.scrollTop = 0; }
      if (document.body.scrollTop) { document.body.scrollTop = 0; }
      var p = fe.parentElement;
      for (var k = 0; k < 4 && p; k++) {
        p.style.setProperty('border', '0', 'important');
        p.style.setProperty('box-shadow', 'none', 'important');
        p = p.parentElement;
      }
    } catch (e) {}
  }
  syncFrame();
  try { setInterval(syncFrame, 800); } catch (e) {}

  var PRACTICE_PAL = ['#2e9e4f', '#4f5fd6', '#d98e15', '#0e7ac4', '#e0719f', '#6d3fc4'];
  var OTHER_GREY = '#aab3bc';
  var RAMP4 = ['#14522c', '#227a43', '#37a55e', '#6cc287'];
  var RAMP3 = ['#14522c', '#37a55e', '#6cc287'];

  function donut(items, palette, greyLast) {
    var total = 0, i;
    items = items || [];
    for (i = 0; i < items.length; i++) { total += items[i].count; }
    var slices = [], cum = 0, GAP = 1.6;
    for (i = 0; i < items.length; i++) {
      var pct = total ? (items[i].count / total * 100) : 0;
      var seg = Math.max(pct - GAP, 0.4);
      var color = (greyLast && items[i].id === '__other__') ? OTHER_GREY
                : palette[Math.min(i, palette.length - 1)];
      slices.push({label: items[i].label, count: items[i].count, id: items[i].id,
                   color: color,
                   dash: seg.toFixed(2) + ' ' + (100 - seg).toFixed(2),
                   offset: String((25 - cum - GAP / 2).toFixed(2))});
      cum += pct;
    }
    return slices;
  }

  c.practiceColor = function(name) {
    var s = c.practiceSlices || [];
    for (var i = 0; i < s.length; i++) { if (s[i].label === name) { return s[i].color; } }
    return OTHER_GREY;
  };
  c.hov = null;
  c.setHov = function(k) { c.hov = k; };
  c.clearHov = function() { c.hov = null; };
  c.ageBucket = function(d) { return d < 7 ? 0 : (d < 14 ? 1 : (d < 30 ? 2 : 3)); };

  /* ---------- Trends: REAL PA daily scores -> three small multiples ----------
     data.trends comes from the server (pa_scores_l1 totals). One shared x-domain
     (the same days) so the crosshair lines up across panels; each panel has its
     own single y-axis, never a dual axis. Built inside build(), so Refresh and the
     record watch re-pull it with the rest of the Pulse. */
  var TR_MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var TR_DAY = 86400000;
  function trMs(k) {
    return Date.UTC(parseInt(k.substr(0, 4), 10), parseInt(k.substr(4, 2), 10) - 1,
                    parseInt(k.substr(6, 2), 10));
  }
  function trLbl(ms) { var d = new Date(ms); return TR_MON[d.getUTCMonth()] + ' ' + d.getUTCDate(); }
  function trNice(mx) {
    if (!(mx > 0)) { return {max: 4, step: 2}; }
    var raw = mx / 3, p = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), m = raw / p;
    var cand = p >= 10 ? [1, 2, 2.5, 5, 10] : [1, 2, 5, 10], st = 10;
    for (var i = 0; i < cand.length; i++) { if (m <= cand[i] + 1e-9) { st = cand[i]; break; } }
    st = Math.max(1, st * p);
    return {max: Math.ceil(mx / st - 1e-9) * st, step: st};
  }
  function trTicks(nc) {
    var out = [];
    for (var v = 0; v <= nc.max + 1e-9; v += nc.step) {
      out.push({v: v, label: String(Math.round(v)), y: 100 - v / nc.max * 100});
    }
    return out;
  }
  function trLine(vals, max, N) {
    var d = '', pen = false, ys = [];
    for (var j = 0; j < N; j++) {
      var v = vals[j];
      if (v === null || v === undefined) { ys.push(null); pen = false; continue; }
      var y = 100 - v / max * 100;
      ys.push(y);
      d += (pen ? 'L' : 'M') + ((j + 0.5) / N * 1000).toFixed(1) + ',' + y.toFixed(2);
      pen = true;
    }
    return {d: d, ys: ys};
  }
  function trLast(vals) {
    for (var j = vals.length - 1; j >= 0; j--) {
      if (vals[j] !== null && vals[j] !== undefined) { return j; }
    }
    return -1;
  }
  function trDelta(vals, li, dp) {
    var k = li - 30;
    if (li < 0 || k < 0 || vals[k] === null || vals[k] === undefined) { return ''; }
    var f = dp ? 10 : 1, r = Math.round((vals[li] - vals[k]) * f) / f;
    if (!r) { return 'no change vs 30d'; }
    return (r > 0 ? '↑ +' : '↓ −') + Math.abs(r).toFixed(dp) + ' vs 30d';
  }
  function buildTrends() {
    var T = $scope.data.trends || {state: 'error', error: 'no trends in the server response'};
    var tr = {state: T.state || 'error', sub: 'daily Performance Analytics scores'};
    c.trHi = null; c.trWk = null; c.trPanel = null;
    if (tr.state !== 'ok') {
      if (tr.state === 'empty') {
        tr.emptyTitle = 'No trend history yet';
        tr.emptyText = 'Performance Analytics has not collected any daily scores for the PTAG ' +
          'indicators on this instance yet, so there is nothing to chart. The backlog, arrivals ' +
          'and average-score trends appear here after the first daily collection runs.';
      } else if (tr.state === 'missing') {
        tr.emptyTitle = 'Trends are not set up on this instance';
        tr.emptyText = 'These Performance Analytics indicators could not be found or read: ' +
          (T.missing || []).join('; ') + '. There is no history to chart until they exist ' +
          'and have collected scores.';
      } else {
        tr.emptyTitle = 'Trends could not be loaded';
        tr.emptyText = 'The Pulse could not read Performance Analytics scores' +
          (T.error ? ' (' + T.error + ')' : '') + '. The rest of the Pulse is unaffected.';
      }
      c.tr = tr;
      return;
    }
    var days = T.days || [], N = days.length, i, ms0 = [];
    for (i = 0; i < N; i++) { ms0.push(trMs(days[i])); }
    tr.n = N;
    tr.sub = 'daily Performance Analytics scores, ' + trLbl(ms0[0]) + ' – ' +
             trLbl(ms0[N - 1]) + ', ' + new Date(ms0[N - 1]).getUTCFullYear();
    tr.xs = []; tr.xticks = []; tr.tips = [];
    var avgV = [];
    for (i = 0; i < N; i++) {
      tr.xs.push((i + 0.5) / N * 100);
      var dd = new Date(ms0[i]);
      if (dd.getUTCDate() === 1) { tr.xticks.push({x: tr.xs[i], label: TR_MON[dd.getUTCMonth()] + ' 1'}); }
      var o = T.open[i], nw = T.neu[i], av = T.avg[i];
      /* PA stores 0 for the average of an EMPTY set. With no open requests there
         is no average, so that day is a gap, not a score of 0. */
      avgV.push(o === 0 ? null : (av === undefined ? null : av));
      tr.tips.push({date: trLbl(ms0[i]) + ', ' + dd.getUTCFullYear(),
                    open: (o === null || o === undefined) ? 'no score' : String(Math.round(o)),
                    avg: o === 0 ? 'n/a' : ((av === null || av === undefined) ? 'no score' : av.toFixed(1)),
                    avgNote: o === 0 ? 'no open requests' : '',
                    neu: (nw === null || nw === undefined) ? 'no score' : String(Math.round(nw))});
    }
    /* weekly arrivals: calendar weeks (Mon-Sun) summed from the DAILY New series */
    var weeks = [], wOf = [], cur = null, total = 0;
    for (i = 0; i < N; i++) {
      var dow = (new Date(ms0[i]).getUTCDay() + 6) % 7, ws = ms0[i] - dow * TR_DAY;
      if (!cur || cur.ws !== ws) {
        cur = {ws: ws, first: i, last: i, n: 0, sum: 0, miss: 0};
        weeks.push(cur);
      }
      cur.last = i; cur.n++;
      var nv = T.neu[i];
      if (nv === null || nv === undefined) { cur.miss++; } else { cur.sum += nv; total += nv; }
      wOf.push(weeks.length - 1);
    }
    var wmx = 0;
    for (i = 0; i < weeks.length; i++) { if (weeks[i].sum > wmx) { wmx = weeks[i].sum; } }
    var wN = trNice(wmx);
    for (i = 0; i < weeks.length; i++) {
      var w = weeks[i], notes = [];
      w.sum = Math.round(w.sum);
      w.left = w.first / N * 100;
      w.width = w.n / N * 100;
      w.cx = (w.first + w.last + 1) / 2 / N * 100;
      w.h = w.sum / wN.max * 100;
      w.part = w.n < 7;
      w.range = trLbl(w.ws) + ' – ' + trLbl(w.ws + 6 * TR_DAY);
      if (w.part) { notes.push((w.last === N - 1 ? 'latest week, ' : '') + w.n + ' of 7 days in the window'); }
      if (w.miss) { notes.push(w.miss + ' day' + (w.miss === 1 ? '' : 's') + ' without a score'); }
      w.note = notes.join('; ');
    }
    tr.weeks = weeks; tr.wOf = wOf; tr.weekTotal = Math.round(total);
    var omx = 0;
    for (i = 0; i < N; i++) { if (T.open[i] > omx) { omx = T.open[i]; } }
    var oN = trNice(omx), oL = trLine(T.open, oN.max, N), li = trLast(T.open);
    var aL = trLine(avgV, 100, N), ai = trLast(avgV);
    var oVal = li < 0 ? '—' : String(Math.round(T.open[li]));
    var aVal = ai < 0 ? '—' : avgV[ai].toFixed(1);
    var oD = trDelta(T.open, li, 0), aD = trDelta(avgV, ai, 1);
    tr.panels = [
      {key: 'open', kind: 'line', title: 'Open backlog', note: 'non-terminal requests, incl. On Hold',
       value: oVal, delta: oD, ticks: trTicks(oN), d: oL.d, ys: oL.ys, end: li,
       aria: 'Open backlog, daily: ' + oVal + (li < 0 ? '' : ' on ' + tr.tips[li].date) + (oD ? ', ' + oD : '') + '.',
       hint: 'Open backlog chart. Left and right arrow keys step one day.'},
      {key: 'neu', kind: 'bar', title: 'Arrivals per week', note: 'new requests, weekly totals',
       value: String(tr.weekTotal), delta: 'in ' + N + ' days', ticks: trTicks(wN), weeks: weeks,
       aria: 'Arrivals per week: ' + tr.weekTotal + ' new requests across ' + weeks.length + ' weeks.',
       hint: 'Arrivals per week chart. Left and right arrow keys step one week.'},
      {key: 'avg', kind: 'line', title: 'Avg score', note: 'open requests, 0–100 scale',
       value: aVal, delta: aD, ticks: trTicks({max: 100, step: 50}), d: aL.d, ys: aL.ys, end: ai,
       aria: 'Average score of open requests, daily: ' + aVal + (ai < 0 ? '' : ' on ' + tr.tips[ai].date) + (aD ? ', ' + aD : '') + '.',
       hint: 'Average score chart. Left and right arrow keys step one day.'}
    ];
    c.tr = tr;
  }
  c.buildTrends = buildTrends;
  c.trLeave = function() { c.trHi = null; c.trWk = null; c.trPanel = null; };
  function trAt(p, i, w) {
    var tr = c.tr;
    if (p.kind === 'bar') {
      if (w === undefined || w === null) { w = tr.wOf[i]; }
      c.trWk = w; c.trHi = tr.weeks[w].last;
    } else { c.trHi = i; c.trWk = tr.wOf[i]; }
    c.trPanel = p.key;
  }
  c.trMove = function(ev, p) {
    if (!c.tr || c.tr.state !== 'ok') { return; }
    var r = ev.currentTarget.getBoundingClientRect();
    var i = Math.floor((ev.clientX - r.left) / (r.width || 1) * c.tr.n);
    trAt(p, Math.max(0, Math.min(c.tr.n - 1, i)));
  };
  c.trFocus = function(p) {
    if (!c.tr || c.tr.state !== 'ok') { return; }
    if (p.kind === 'bar') { trAt(p, 0, c.tr.weeks.length - 1); }
    else { trAt(p, p.end >= 0 ? p.end : c.tr.n - 1); }
  };
  c.trKey = function(ev, p) {
    var k = ev.keyCode;
    if (!c.tr || c.tr.state !== 'ok' || (k !== 37 && k !== 39)) { return; }
    ev.preventDefault();
    var d = k === 39 ? 1 : -1;
    /* Step from the SHARED crosshair, whichever panel set it (a pointer resting on
       another chart moves it via Chrome's post-scroll mousemove). Only with no
       active crosshair does the first arrow land on the latest point. */
    if (p.kind === 'bar') {
      var W = c.tr.weeks.length;
      var w = c.trWk !== null ? c.trWk + d : W - 1;
      trAt(p, 0, Math.max(0, Math.min(W - 1, w)));
    } else {
      var i = c.trHi !== null ? c.trHi + d : c.tr.n - 1;
      trAt(p, Math.max(0, Math.min(c.tr.n - 1, i)));
    }
  };
  c.trTipX = function(p) {
    if (p.kind === 'bar') { return c.trWk === null ? 0 : c.tr.weeks[c.trWk].cx; }
    return c.trHi === null ? 0 : c.tr.xs[c.trHi];
  };

  function build() {
    var mix = $scope.data.practiceMix || [];
    c.practiceSlices = donut(mix, PRACTICE_PAL, true);
    var ids = [];
    for (var i = 0; i < mix.length && i < 5; i++) {
      if (mix[i].id && mix[i].id !== '__other__') { ids.push(mix[i].id); }
    }
    c.topPracticeIds = ids.join(',');
    var bands = $scope.data.bands || [];
    c.bandSlices = donut(bands, bands.length > 3 ? RAMP4 : RAMP3, false);
    buildTrends();
  }
  build();

  /* I59: value-watch. spUtil.update MERGES data in place, so a reference
     watch on 'data' never fires - that is what left the spinner stuck. */
  $scope.$watch('data.asOf', function(nv, ov) {
    if (nv === ov) { return; }
    build();
    c.refreshing = false;
    if (c.dp && !c.dp.busy && c.dpArgs) { fetchDrill(false); }
  });

  c.refreshing = false;
  c.refresh = function() {
    if (c.refreshing) { return; }
    c.refreshing = true;
    var done = function() { c.refreshing = false; };
    try {
      var p = spUtil.update($scope);
      if (p && p.then) { p.then(done, done); }
    } catch (e) { done(); }
    $timeout(done, 8000);   /* failsafe: never spin forever */
  };


  /* ---- I68: scroll to the drill on open, return on close ---- */
  var savedScroll = null;
  function collectScrollers() {
    /* I68b: the frame is SLOTTED through shadow DOM, so a parentElement/host
       walk BYPASSES the tree that actually scrolls (div.page.scroll-y, proven
       live: unreachable in 100 hops). Scan the whole top document instead -
       same technique the shell widget uses. */
    var list = [];
    try {
      function scan(node, depth) {
        if (!node || depth > 60) { return; }
        if (node.nodeType === 1) {
          try {
            if (node.scrollHeight > node.clientHeight + 4 && node.clientHeight > 100) {
              list.push(node);
            }
          } catch (e) {}
          if (node.shadowRoot) { scan(node.shadowRoot, depth + 1); }
        }
        var kids = node.children || node.childNodes || [];
        for (var i = 0; i < kids.length; i++) { scan(kids[i], depth + 1); }
      }
      scan(window.top.document.documentElement, 0);
    } catch (e) {}
    return list;
  }
  function saveScroll() {
    try {
      savedScroll = collectScrollers().map(function(s) {
        return {el: s, top: s.scrollTop, left: s.scrollLeft};
      });
      savedScroll.push({win: window.top, x: window.top.scrollX, y: window.top.scrollY});
    } catch (e) { savedScroll = null; }
  }
  function restoreScroll() {
    var s = savedScroll;
    savedScroll = null;
    if (!s) { return; }
    function apply() {
      try {
        s.forEach(function(r) {
          if (r.win) { r.win.scrollTo(r.x, r.y); }
          else { r.el.scrollTop = r.top; r.el.scrollLeft = r.left; }
        });
      } catch (e) {}
    }
    $timeout(apply, 80);
    $timeout(apply, 450);
    $timeout(apply, 1300);  /* final pass: outlast the 800ms sync tick, whose
                               height shrink triggers shell scroll anchoring */
  }
  function scrollToDrill() {
    /* I69: ONE motion, not two. Size the frame first (immediate sync instead
       of waiting for the 800ms tick), then a single smooth scroll that lands
       true. The panel grows downward from its pinned top when rows arrive,
       so no corrective second scroll is ever needed. */
    $timeout(syncFrame, 60);
    $timeout(function() {
      try {
        var p = document.getElementById('ptag-drill');
        if (p) { p.scrollIntoView({behavior: 'smooth', block: 'start'}); }
      } catch (e) {}
    }, 220);
  }

  /* ---------- drill ---------- */
  c.cols = [
    {key: 'number', label: 'Number', w: '110px'},
    {key: 'title', label: 'Title'},
    {key: 'practice', label: 'Practice', w: '170px'},
    {key: 'state', label: 'State', w: '150px'},
    {key: 'score', label: 'Score', w: '80px', num: true},
    {key: 'age', label: 'Age', w: '80px', num: true},
    {key: 'updated_ms', label: 'Updated', w: '150px', num: true}
  ];
  var NUMERIC = {score: 1, age: 1, updated_ms: 1};

  function matchTerm(r, key, t) {
    if (key === 'score' || key === 'age') {
      var m = t.match(/^(>=|<=|>|<)\s*(-?\d+)$/);
      if (m) {
        var v = r[key];
        if (v === null || v === undefined) { return false; }
        var n = parseInt(m[2], 10);
        if (m[1] === '>') { return v > n; }
        if (m[1] === '<') { return v < n; }
        if (m[1] === '>=') { return v >= n; }
        return v <= n;
      }
    }
    var raw = (key === 'updated_ms') ? r.updated : r[key];
    if (raw === null || raw === undefined) { raw = ''; }
    return String(raw).toLowerCase().indexOf(t) > -1;
  }
  function matchCell(r, key, query) {
    var qq = String(query || '').trim();
    if (!qq) { return true; }
    /* comma = OR within the column; columns AND together */
    var terms = qq.split(',');
    var any = false;
    for (var i = 0; i < terms.length; i++) {
      var t = terms[i].trim().toLowerCase();
      if (!t) { continue; }
      any = true;
      if (matchTerm(r, key, t)) { return true; }
    }
    return !any;
  }
  c.filtersOn = function() {
    if (!c.dp) { return false; }
    var f = c.dp.filters || {};
    for (var k in f) { if (String(f[k] || '').trim()) { return true; } }
    return false;
  };
  c.applyFilter = function() {
    if (!c.dp) { return; }
    var f = c.dp.filters || {};
    c.dp.view = c.dp.rows.filter(function(r) {
      for (var i = 0; i < c.cols.length; i++) {
        if (!matchCell(r, c.cols[i].key, f[c.cols[i].key])) { return false; }
      }
      return true;
    });
    c.dp.page = 1;
    applySort();
  };
  c.clearCols = function() {
    if (!c.dp) { return; }
    c.dp.filters = {};
    c.applyFilter();
  };

  function fetchDrill(showBusy) {
    if (showBusy) { c.dp.busy = true; }
    var a = c.dpArgs;
    $scope.server.get({action: 'drill', kind: a.kind, value: a.value, ids: a.ids || ''})
      .then(function(r) {
        if (!c.dp) { return; }
        c.dp.rows = (r.data && r.data.drill) || [];
        c.applyFilter();
        c.dp.busy = false;
        /* I70: glide only AFTER the rows land - the panel is at final size,
           so nothing regrows mid-flight and nothing jumps back. */
        if (showBusy) { scrollToDrill(); }
      }, function() { if (c.dp) { c.dp.busy = false; } });
  }

  c.drill = function(kind, value, label, slot, sortHint) {
    if (c.dp && c.dp.label === label) { c.closeDrill(); return; }
    if (!c.dp) { saveScroll(); }   /* fresh open: remember where the user was */
    var sortKey = sortHint === 'score' ? 'score' : (sortHint === 'updated' ? 'updated_ms' : 'age');
    c.dpArgs = {kind: kind, value: String(value),
                ids: (kind === 'practice' && String(value) === '__other__') ? c.topPracticeIds : ''};
    c.dp = {label: label, slot: slot, sort: sortKey, dir: -1, rows: [], view: [],
            filters: {}, page: 1, busy: true};
    fetchDrill(true);
  };
  c.drillPractice = function(s) {
    var v = s.id === '__other__' ? '__other__' : (s.id ? s.id : '__none__');
    c.drill('practice', v, 'Practice: ' + s.label, 3, 'age');
  };
  c.closeDrill = function() { c.dp = null; c.dpArgs = null;
    $timeout(syncFrame, 60); $timeout(syncFrame, 320);
    restoreScroll(); };

  function applySort() {
    if (!c.dp) { return; }
    var key = c.dp.sort, dir = c.dp.dir, num = NUMERIC[key];
    c.dp.view.sort(function(a, b) {
      var av = a[key], bv = b[key];
      if (num) {
        av = (av === null || av === undefined) ? -Infinity : av;
        bv = (bv === null || bv === undefined) ? -Infinity : bv;
        return (av - bv) * dir;
      }
      return String(av).localeCompare(String(bv)) * dir;
    });
    repage();
  }
  var PAGE_SIZE = 10;
  function repage() {
    if (!c.dp) { return; }
    c.dp.pageCount = Math.max(1, Math.ceil(c.dp.view.length / PAGE_SIZE));
    if (!c.dp.page || c.dp.page < 1) { c.dp.page = 1; }
    if (c.dp.page > c.dp.pageCount) { c.dp.page = c.dp.pageCount; }
    var s = (c.dp.page - 1) * PAGE_SIZE;
    c.dp.paged = c.dp.view.slice(s, s + PAGE_SIZE);
  }
  c.rangeStart = function() {
    return (c.dp && c.dp.view.length) ? (c.dp.page - 1) * PAGE_SIZE + 1 : 0;
  };
  c.rangeEnd = function() {
    return c.dp ? Math.min(c.dp.page * PAGE_SIZE, c.dp.view.length) : 0;
  };
  c.prevPage = function() { if (c.dp && c.dp.page > 1) { c.dp.page--; repage(); } };
  c.nextPage = function() {
    if (c.dp && c.dp.page < c.dp.pageCount) { c.dp.page++; repage(); }
  };
  c.sortBy = function(key) {
    if (!c.dp) { return; }
    if (c.dp.sort === key) { c.dp.dir = -c.dp.dir; }
    else { c.dp.sort = key; c.dp.dir = 1; }
    applySort();
  };

  c.recUrl = function(r) {
    return '/now/ptag-engagement-hub/record/x_snc_ptag_engage_engagement_request/' + r.id;
  };
  c.openRec = function(r) {
    var url = c.recUrl(r);
    /* I60: client-side route push - the workspace router opens the record as
       a CHILD TAB with no page reload (proven live: marker survived, subtab
       rendered). Fallback = old full navigation. */
    try {
      var t = window.top;
      t.history.pushState({}, '', url);
      t.dispatchEvent(new t.PopStateEvent('popstate', {state: {}}));
      return;
    } catch (e) {}
    try { window.top.location.href = url; } catch (e2) { window.location.href = url; }
  };
  c.openRecA = function(ev, r) {
    /* Number link: plain left-click routes client-side; ctrl/meta/shift or
       middle-click keep native link behavior (new browser tab). */
    if (ev.ctrlKey || ev.metaKey || ev.shiftKey || ev.button === 1) {
      ev.stopPropagation();
      return;
    }
    ev.preventDefault();
    ev.stopPropagation();
    c.openRec(r);
  };

  function onKey(ev) {
    if (ev.keyCode === 27 && c.dp) { $scope.$apply(function() { c.closeDrill(); }); }
  }
  document.addEventListener('keydown', onKey);
  $scope.$on('$destroy', function() { document.removeEventListener('keydown', onKey); });

  try {
    spUtil.recordWatch($scope, 'x_snc_ptag_engage_engagement_request', '',
      function() { spUtil.update($scope); });
  } catch (e) {}
}

sp_widget.css:
.pt-cc { min-height: 640px; color: #16181c;
  font-family: "Source Sans Pro", "Segoe UI", system-ui, -apple-system, Roboto, Arial, sans-serif;
  background: #f1f3f5; }
.pt-cc__wrap { max-width: 1400px; margin: 0 auto; padding: 26px 28px 30px; }

/* ---- flat cards, subtle borders ---- */
.pt-cc .glass-card { background: #ffffff; border: 1px solid #adb8c2; border-radius: 14px;
  box-shadow: 0 1px 2px rgba(22, 24, 28, 0.04), 0 4px 12px rgba(22, 24, 28, 0.04);
  padding: 20px 22px; min-width: 0; }
.pt-cc .glass-card--interactive { cursor: pointer;
  transition: transform 160ms cubic-bezier(0.2, 0, 0, 1), box-shadow 160ms cubic-bezier(0.2, 0, 0, 1),
    border-color 160ms; }
.pt-cc .glass-card--interactive:hover { transform: translateY(-1px); border-color: #8a97a3;
  box-shadow: 0 2px 4px rgba(22, 24, 28, 0.05), 0 10px 24px rgba(22, 24, 28, 0.08); }
.pt-cc .glass-card--active { border-color: #2e9e4f;
  box-shadow: 0 0 0 1px #2e9e4f, 0 4px 12px rgba(22, 24, 28, 0.06); }
.pt-cc [role="button"]:focus-visible { outline: 2px solid #2e9e4f; outline-offset: 2px; }

/* ---- header ---- */
.pt-cc__head { display: flex; align-items: flex-end; justify-content: space-between;
  gap: 14px; margin-bottom: 20px; }
.pt-cc__title { font-size: 24px; font-weight: 700; letter-spacing: -0.01em; color: #16181c; }
.pt-cc__sub { font-size: 12px; color: #667080; margin-top: 2px; display: flex; align-items: center; gap: 6px; }
.pt-cc__live { width: 6px; height: 6px; border-radius: 50%; background: #2e9e4f;
  animation: pt-cc-live 2.4s ease-in-out infinite; }
@keyframes pt-cc-live { 0% { opacity: 1; } 50% { opacity: 0.35; } 100% { opacity: 1; } }
.pt-cc__hr { display: flex; align-items: center; gap: 12px; }
.pt-cc__asof { font-size: 11px; color: #667080; }
.pt-cc__refresh { display: inline-flex; align-items: center; gap: 6px; background: #ffffff;
  border: 1px solid #adb8c2; border-radius: 10px; padding: 7px 12px; font-size: 12px;
  font-weight: 600; color: #227a43; cursor: pointer;
  box-shadow: 0 1px 2px rgba(22, 24, 28, 0.04);
  transition: box-shadow 160ms cubic-bezier(0.2, 0, 0, 1), border-color 160ms; }
.pt-cc__refresh:hover { border-color: #8a97a3; box-shadow: 0 4px 12px rgba(22, 24, 28, 0.08); }
.pt-cc__ric { width: 13px; height: 13px; }
.pt-cc__refresh.is-busy .pt-cc__ric { animation: pt-cc-spin 0.9s linear infinite; }
@keyframes pt-cc-spin { to { transform: rotate(360deg); } }

/* ---- KPI strip ---- */
.pt-cc__kpis { display: grid; grid-template-columns: repeat(5, 1fr); gap: 20px; margin-bottom: 20px; }
.pt-cc__kpi { position: relative; padding: 16px 18px; }
.pt-cc__kpi--green::before, .pt-cc__kpi--amber::before { content: ''; position: absolute;
  left: 0; top: 18px; width: 3px; height: 20px; border-radius: 0 3px 3px 0; }
.pt-cc__kpi--green::before { background: #2e9e4f; }
.pt-cc__kpi--amber::before { background: #b8790e; }
.pt-cc__kn { font-size: 30px; font-weight: 700; color: #16181c; line-height: 1.1; }
.pt-cc__kl { font-size: 12px; font-weight: 500; color: #5b6572; margin-top: 3px; }

/* ---- rows ---- */
.pt-cc__row { display: grid; gap: 20px; margin-bottom: 20px; }
.pt-cc__row--mid { grid-template-columns: 7fr 5fr; }
.pt-cc__row--duo { grid-template-columns: 1fr 1fr; }
.pt-cc__ct { margin: 0 0 14px; font-size: 14px; font-weight: 600; color: #16181c;
  display: flex; align-items: center; }
.pt-cc__cs { font-weight: 400; font-size: 12px; color: #667080; margin-left: 6px; }

/* ---- pipeline bars ---- */
.pt-cc__bar { display: flex; align-items: center; gap: 10px; height: 30px; border-radius: 8px;
  padding: 0 6px; cursor: pointer; transition: background 120ms ease-out, opacity 150ms ease-out; }
.pt-cc__bar:hover, .pt-cc__bar.is-open { background: rgba(46, 158, 79, 0.08); }
.pt-cc__card--pipeline:hover .pt-cc__bar:not(:hover) { opacity: 0.45; }
.pt-cc__bar:hover .pt-cc__bf { filter: brightness(1.06); }
.pt-cc__bl { flex: 0 0 130px; font-size: 12px; color: #5b6572; text-align: right; }
.pt-cc__bt { flex: 1; height: 12px; border-radius: 6px; background: #eef1f4; overflow: hidden; }
.pt-cc__bf { display: block; height: 100%; border-radius: 0 4px 4px 0; min-width: 2px;
  background: #2e9e4f; transition: width 400ms cubic-bezier(0.16, 1, 0.3, 1); }
.pt-cc__bar.is-attn .pt-cc__bf { background: #b8790e; }
.pt-cc__bar.is-neg .pt-cc__bf { background: #cf4437; }
/* On Hold (10): paused, open. fuchsia-700 on the light canvas (validator: CVD dE >= 17 vs the set) */
.pt-cc__bar.is-hold .pt-cc__bf { background: #a21caf; }
.pt-cc__bn { flex: 0 0 28px; font-size: 12px; font-weight: 600; color: #16181c;
  font-variant-numeric: tabular-nums; }
.pt-cc__bn.is-zero { color: #667080; font-weight: 400; }

/* ---- queue age heat ---- */
.pt-cc__heat { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.pt-cc__cell { border-radius: 12px; min-height: 88px; padding: 14px 8px; text-align: center;
  cursor: pointer; transition: transform 160ms cubic-bezier(0.2, 0, 0, 1), box-shadow 160ms,
    opacity 150ms ease-out; }
.pt-cc__heat:hover .pt-cc__cell:not(:hover):not(.is-zero) { opacity: 0.55; }
.pt-cc__cell:hover:not(.is-zero) { transform: translateY(-2px) scale(1.03);
  box-shadow: 0 10px 22px rgba(22, 24, 28, 0.14); }
.pt-cc__cell.is-open { box-shadow: 0 0 0 2px #2e9e4f; }
.pt-cc__cell.sev-0 { background: #e6f4ea; border: 1px solid rgba(29, 122, 56, 0.18); }
.pt-cc__cell.sev-0 .pt-cc__cn, .pt-cc__cell.sev-0 .pt-cc__cl { color: #1d7a38; }
.pt-cc__cell.sev-1 { background: #fbf0d9; border: 1px solid rgba(138, 95, 14, 0.18); }
.pt-cc__cell.sev-1 .pt-cc__cn, .pt-cc__cell.sev-1 .pt-cc__cl { color: #8a5f0e; }
.pt-cc__cell.sev-2 { background: #fae8d8; border: 1px solid rgba(150, 73, 26, 0.18); }
.pt-cc__cell.sev-2 .pt-cc__cn, .pt-cc__cell.sev-2 .pt-cc__cl { color: #96491a; }
.pt-cc__cell.sev-3 { background: #fae3e1; border: 1px solid rgba(168, 50, 40, 0.18); }
.pt-cc__cell.sev-3 .pt-cc__cn, .pt-cc__cell.sev-3 .pt-cc__cl { color: #a83228; }
.pt-cc__cell.is-zero { background: #f6f8f9; border: 1px solid #e9edf1; cursor: default; }
.pt-cc__cell.is-zero .pt-cc__cn, .pt-cc__cell.is-zero .pt-cc__cl { color: #8b94a0; }
.pt-cc__cn { font-size: 24px; font-weight: 700; }
.pt-cc__cl { font-size: 11px; font-weight: 500; margin-top: 2px; }

/* ---- donuts ---- */
.pt-cc__dwrap { display: flex; align-items: center; gap: 20px; }
.pt-cc__dring { position: relative; flex: 0 0 140px; }
.pt-cc__donut { width: 140px; height: 140px; display: block; }
.pt-cc__donut circle { fill: none; }
.pt-cc__dbg { stroke: #eef1f4; stroke-width: 5.4; }
.pt-cc__seg { cursor: pointer; pointer-events: visibleStroke;
  transition: stroke-width 150ms ease-out, opacity 150ms ease-out, filter 150ms ease-out; }
.pt-cc__seg:hover, .pt-cc__seg.is-hov { stroke-width: 7.2;
  filter: brightness(1.08) drop-shadow(0 1px 2px rgba(22, 24, 28, 0.25)); }
.pt-cc__seg.is-dim { opacity: 0.4; }
.pt-cc__dcenter { position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center; pointer-events: none; }
.pt-cc__dcenter b { font-size: 22px; font-weight: 700; color: #16181c; line-height: 1.05; }
.pt-cc__dcenter span { font-size: 11px; color: #667080; }
.pt-cc__legend { list-style: none; margin: 0; padding: 0; font-size: 12px; min-width: 0; flex: 1; }
.pt-cc__legend li { display: flex; align-items: center; gap: 7px; padding: 4px 6px;
  border-radius: 6px; cursor: pointer; transition: background 120ms ease-out; }
.pt-cc__legend li:hover, .pt-cc__legend li.is-open { background: rgba(46, 158, 79, 0.05); }
.pt-cc__lgl { color: #16181c; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pt-cc__legend b { color: #16181c; margin-left: auto; padding-left: 8px;
  font-variant-numeric: tabular-nums; }
.pt-cc__sw { width: 10px; height: 10px; border-radius: 3px; flex: 0 0 10px; }
.pt-cc__none { color: #667080; font-size: 12px; }

/* ---- drill panel ---- */
.pt-cc__drill { margin-bottom: 20px; background: #ffffff; border: 1px solid #adb8c2;
  box-shadow: 0 1px 2px rgba(22, 24, 28, 0.04), 0 10px 28px rgba(22, 24, 28, 0.08);
  padding: 0; overflow: hidden; animation: pt-cc-open 240ms cubic-bezier(0.2, 0, 0, 1); }
@keyframes pt-cc-open { from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); } }
.pt-cc__dhead { display: flex; align-items: center; gap: 12px; height: 48px; padding: 0 16px; }
.pt-cc__fchip { background: #227a43; color: #ffffff; font-size: 12px; font-weight: 600;
  padding: 4px 12px; border-radius: 999px; white-space: nowrap; }
.pt-cc__dcount { font-size: 13px; color: #5b6572; }
.pt-cc__dspace { flex: 1; }
.pt-cc__ghost { background: transparent; border: 0; color: #227a43; font-size: 13px;
  font-weight: 600; padding: 6px 10px; border-radius: 8px; cursor: pointer; }
.pt-cc__ghost:hover { background: rgba(46, 158, 79, 0.08); }
.pt-cc__x { background: transparent; border: 0; width: 28px; height: 28px; border-radius: 8px;
  font-size: 18px; color: #5b6572; cursor: pointer; line-height: 1; }
.pt-cc__x:hover { background: #eef1f4; }
.pt-cc__dbusy { padding: 24px 16px; font-size: 13px; color: #667080; }
.pt-cc__tblwrap { overflow: visible; }
.pt-cc__tbl { width: 100%; border-collapse: collapse; table-layout: fixed; }
.pt-cc__tbl th { position: sticky; top: 0; background: #fafbfc; z-index: 1; text-align: left;
  border-bottom: 1px solid #adb8c2; padding: 0; }
.pt-cc__tbl .pt-cc__frow th { top: 33px; padding: 5px 8px; background: #fafbfc; }
.pt-cc__fin { width: 100%; height: 26px; border: 1px solid #d5dce2; border-radius: 6px;
  padding: 0 8px; font-size: 12px; color: #16181c; background: #ffffff; box-sizing: border-box; }
.pt-cc__fin:focus { outline: none; border-color: #2e9e4f; box-shadow: 0 0 0 2px rgba(46, 158, 79, 0.15); }
.pt-cc__fin::placeholder { color: #aab3bc; }
.pt-cc__tbl th.is-num { text-align: right; }
.pt-cc__tbl thead tr:first-child th button { width: 100%; background: transparent; border: 0;
  cursor: pointer; padding: 9px 12px; font-size: 11px; font-weight: 600; letter-spacing: 0.05em;
  text-transform: uppercase; color: #5b6572; text-align: inherit; }
.pt-cc__tbl th.is-sorted button { color: #16181c; }
.pt-cc__chev { margin-left: 4px; font-size: 8px; }
.pt-cc__tbl td { padding: 0 12px; height: 40px; font-size: 13px; color: #16181c;
  border-bottom: 1px solid #eef1f4; overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap; }
.pt-cc__tbl tbody tr { cursor: pointer; transition: background 120ms ease-out; }
.pt-cc__tbl tbody tr:hover { background: rgba(46, 158, 79, 0.05); }
.pt-cc__tbl tbody tr:focus-visible { outline: 2px solid #2e9e4f; outline-offset: -2px; }
.pt-cc__numlink { color: #1d7a38; font-weight: 600; text-decoration: none; }
.pt-cc__numlink:hover { text-decoration: underline; }
.pt-cc__pdot { display: inline-block; width: 8px; height: 8px; border-radius: 50%;
  margin-right: 7px; vertical-align: baseline; }
.pt-cc__num { text-align: right; font-variant-numeric: tabular-nums; }
.pt-chip2 { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 11px;
  font-weight: 700; }
.pt-chip2--happy { background: #227a43; color: #ffffff; }
.pt-chip2--attn { background: #f2b84b; color: #5c4306; }
.pt-chip2--neg { background: #b0362c; color: #ffffff; }
.pt-chip2--hold { background: #a21caf; color: #ffffff; }
.pt-cc__agec.age-1 { color: #8a5f0e; font-weight: 600; }
.pt-cc__agec.age-2 { color: #96491a; font-weight: 600; }
.pt-cc__agec.age-3 { color: #a83228; font-weight: 600; }
.pt-cc__nomatch { padding: 20px 16px; font-size: 13px; color: #667080; }
.pt-cc__dempty { text-align: center; padding: 48px 16px; }
.pt-cc__de-t { font-size: 14px; font-weight: 600; color: #16181c; }
.pt-cc__de-s { font-size: 13px; color: #667080; margin: 4px 0 12px; }
.pt-cc__denied { padding: 22px; color: #667080; font-size: 13px; }

/* ---- responsive ---- */
@media (max-width: 1100px) { .pt-cc__kpis { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 980px) {
  .pt-cc__row--mid, .pt-cc__row--duo { grid-template-columns: 1fr; }
  .pt-cc__upd { display: none; }
}

/* ---- reduced motion ---- */
@media (prefers-reduced-motion: reduce) {
  .pt-cc *, .pt-cc *::before, .pt-cc *::after {
    animation-duration: 0.01ms !important; animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important; }
  .pt-cc__live { animation: none; opacity: 1; }
}

/* ---- I62: drill pager (fixed 10/page) ---- */
.pt-cc__pager { display: flex; align-items: center; gap: 10px; padding: 8px 16px;
  border-top: 1px solid #eef1f4; }
.pt-cc__prange { font-size: 12px; color: #667080; }
.pt-cc__pspace { flex: 1; }
.pt-cc__ppos { font-size: 12px; color: #5b6572; font-variant-numeric: tabular-nums; }
.pt-cc__pbtn { width: 28px; height: 28px; border: 1px solid #adb8c2; border-radius: 8px;
  background: #ffffff; color: #227a43; font-size: 10px; cursor: pointer; line-height: 1; }
.pt-cc__pbtn:hover:not(:disabled) { background: rgba(46, 158, 79, 0.08); }
.pt-cc__pbtn:disabled { opacity: 0.4; cursor: default; }

/* ---- I63: hover pop + view-all ---- */
.pt-cc__all { margin-left: auto; background: transparent; border: 1px solid #adb8c2;
  border-radius: 8px; padding: 3px 10px; font-size: 11px; font-weight: 600; color: #227a43;
  cursor: pointer; transition: background 120ms, border-color 120ms; }
.pt-cc__all:hover { background: rgba(46, 158, 79, 0.08); border-color: #8a97a3; }
.pt-cc__bt { transition: transform 150ms ease-out; }
.pt-cc__bar:hover .pt-cc__bt { transform: scaleY(1.6); }
.pt-cc__bn { transition: transform 150ms ease-out, color 150ms ease-out; }
.pt-cc__bar:hover .pt-cc__bn { transform: scale(1.4); color: #227a43; }
.pt-cc__bar:hover .pt-cc__bf { filter: brightness(1.1) drop-shadow(0 1px 2px rgba(22, 24, 28, 0.3)); }
.pt-cc__bl { transition: color 150ms ease-out, font-weight 150ms; }
.pt-cc__bar:hover .pt-cc__bl { color: #16181c; font-weight: 600; }
.pt-cc__dcenter--btn { pointer-events: none; }
.pt-cc__dcenter--btn b, .pt-cc__dcenter--btn span { pointer-events: auto; cursor: pointer; }
.pt-cc__dcenter--btn:hover b { color: #227a43; }

/* ---- Trends: REAL PA daily scores, three small multiples (one y-axis each, never dual) ----
   Pulse inks only: series #2e9e4f (validator PASS on #fff), grid #eef1f4, baseline #c9d1d8,
   axis/label #5b6572, muted #667080, value #16181c. Hover = the I63 pop: hovered mark
   brightens + drop shadow, the rest dim to .45. */
.pt-cc__tr-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
.pt-cc__tr-panel { min-width: 0; }
.pt-cc__tr-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px;
  margin-bottom: 12px; }
.pt-cc__tr-hl { min-width: 0; }
.pt-cc__tr-hr { flex: 0 0 auto; text-align: right; }
.pt-cc__tr-t { font-size: 12px; font-weight: 600; color: #16181c; }
.pt-cc__tr-n { font-size: 11px; color: #667080; margin-top: 2px; white-space: nowrap; }
.pt-cc__tr-v { font-size: 22px; font-weight: 700; color: #16181c; line-height: 1.05; }
.pt-cc__tr-body { position: relative; padding-left: 28px; }
.pt-cc__tr-plot { position: relative; height: 140px; }
.pt-cc__tr-gl { position: absolute; left: 0; right: 0; height: 0; border-top: 1px solid #eef1f4; }
.pt-cc__tr-gl.is-base { border-top-color: #c9d1d8; }
.pt-cc__tr-gl span { position: absolute; right: 100%; margin-right: 6px; top: -7px; font-size: 10px;
  line-height: 14px; color: #5b6572; white-space: nowrap; font-variant-numeric: tabular-nums; }
.pt-cc__tr-svg { position: absolute; left: 0; top: 0; width: 100%; height: 100%; overflow: visible;
  pointer-events: none; }
.pt-cc__tr-line { fill: none; stroke: #2e9e4f; stroke-width: 2px; vector-effect: non-scaling-stroke;
  stroke-linejoin: round; stroke-linecap: round; }
.pt-cc__tr-layer { position: absolute; left: 0; top: 0; right: 0; bottom: 0; pointer-events: none; }
.pt-cc__tr-slot { position: absolute; top: 0; bottom: 0; display: flex; align-items: flex-end;
  justify-content: center; }
.pt-cc__tr-bar { display: block; width: calc(100% - 4px); max-width: 24px; background: #2e9e4f;
  border-radius: 4px 4px 0 0; transition: opacity 150ms ease-out, filter 150ms ease-out; }
.pt-cc__tr-bar.is-zero { height: 2px !important; background: #c9d1d8; border-radius: 1px; }
.pt-cc__tr-slot.is-part .pt-cc__tr-bar { opacity: 0.45; }
.pt-cc__tr-plot.is-hov .pt-cc__tr-slot:not(.is-hi) .pt-cc__tr-bar { opacity: 0.45; }
.pt-cc__tr-plot.is-hov .pt-cc__tr-slot.is-part:not(.is-hi) .pt-cc__tr-bar { opacity: 0.25; }
/* MEASURED 2026-09-28: the widget SCSS compile silently DROPS a filter value containing
   drop-shadow(... rgba(...)) (also kills the I63 pipeline/donut pops). brightness() alone compiles,
   so the lift is a box-shadow on the bar instead. */
.pt-cc__tr-slot.is-hi .pt-cc__tr-bar { opacity: 1; filter: brightness(1.1);
  box-shadow: 0 1px 3px rgba(22, 24, 28, 0.3); }
.pt-cc__tr-slot.is-part.is-hi .pt-cc__tr-bar { opacity: 0.6; }
.pt-cc__tr-cross { position: absolute; top: 0; bottom: 0; width: 0; border-left: 1px solid #8a97a3;
  pointer-events: none; }
.pt-cc__tr-dot { position: absolute; width: 8px; height: 8px; margin: -4px 0 0 -4px; border-radius: 50%;
  background: #2e9e4f; box-shadow: 0 0 0 2px #ffffff; pointer-events: none; }
.pt-cc__tr-dot.is-hi { transform: scale(1.35);
  box-shadow: 0 0 0 2px #ffffff, 0 1px 3px rgba(22, 24, 28, 0.35); }
.pt-cc__tr-hit { position: absolute; left: 0; top: 0; right: 0; bottom: 0; z-index: 2; cursor: crosshair;
  border-radius: 4px; }
.pt-cc__tr-hit:focus { outline: none; }
.pt-cc__tr-hit:focus-visible { outline: 2px solid #2e9e4f; outline-offset: 4px; }
.pt-cc__tr-tip { position: absolute; top: 0; z-index: 3; pointer-events: none; background: #ffffff;
  border: 1px solid #adb8c2; border-radius: 8px; padding: 6px 9px; font-size: 11px; color: #5b6572;
  white-space: nowrap; box-shadow: 0 4px 12px rgba(22, 24, 28, 0.12); }
.pt-cc__tr-tip.is-l { transform: translateX(10px); }
.pt-cc__tr-tip.is-r { transform: translateX(-100%) translateX(-10px); }
.pt-cc__tr-td { font-weight: 600; color: #16181c; margin-bottom: 3px; }
.pt-cc__tr-tr { line-height: 17px; }
.pt-cc__tr-tr b { color: #16181c; font-size: 12px; font-variant-numeric: tabular-nums; }
.pt-cc__tr-tn { color: #667080; font-size: 11px; }
.pt-cc__tr-x { position: relative; height: 14px; margin-top: 6px; }
.pt-cc__tr-x span { position: absolute; top: 0; transform: translateX(-50%); font-size: 10px; color: #5b6572;
  white-space: nowrap; }
.pt-cc__tr-empty { text-align: center; padding: 30px 16px 26px; }
.pt-cc__tr-tblw { overflow-x: auto; }
.pt-cc__tr-tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.pt-cc__tr-tbl th { text-align: left; font-size: 11px; font-weight: 600; letter-spacing: 0.05em;
  text-transform: uppercase; color: #5b6572; padding: 8px 12px; border-bottom: 1px solid #adb8c2;
  background: #fafbfc; }
.pt-cc__tr-tbl td { padding: 7px 12px; color: #16181c; border-bottom: 1px solid #eef1f4; }
.pt-cc__tr-tbl .is-num { text-align: right; font-variant-numeric: tabular-nums; }
.pt-cc__tr-tbl tfoot td { font-weight: 700; border-bottom: 0; }
.pt-cc__tr-cap { caption-side: bottom; text-align: left; font-size: 11px; color: #667080; padding-top: 8px; }
@media (max-width: 980px) { .pt-cc__tr-grid { grid-template-columns: 1fr; } }

sp_widget.script:
(function() {
  /* I58: Engagement Pulse - light-glass analytics + drill lists. Staff-gated. */
  var TABLE = 'x_snc_ptag_engage_engagement_request';
  data.denied = false;
  try {
    if (!new x_snc_ptag_engage.PTAGHubAccess().isStaff()) { data.denied = true; return; }
  } catch (e) { data.denied = true; return; }

  var LABELS = {'1':'Submitted','-1':'Under Review','2':'In Backlog','4':'Planned',
                '5':'In Development','10':'On Hold','3':'Completed','-2':'Need More Info',
                '7':'Unlikely','9':'Cancelled','8':'Duplicate'};
  var HAPPY = ['1','-1','2','4','5','3'];
  var BRANCH = ['-2','7','8','9'];
  var KIND = {'-2':'attn','10':'hold','7':'neg','8':'neg','9':'neg'};
  var ACTIVE_STATES = ['1','-1','-2','2','4','5','10'];
  var nowMs = new GlideDateTime().getNumericValue();

  function ageDays(gr) {
    var entered = gr.getValue('state_entered_on') || gr.getValue('sys_created_on');
    var d = Math.floor((nowMs - new GlideDateTime(entered).getNumericValue()) / 86400000);
    return d < 0 ? 0 : d;
  }

  /* ---------- drill: filtered row list ---------- */
  if (input && input.action === 'drill') {
    var kind = String(input.kind || '');
    var val = String(input.value || '');
    var rows = [];
    var jsFilter = null;
    var g = new GlideRecord(TABLE);
    if (kind === 'state') { g.addQuery('state', val); }
    else if (kind === 'practice') {
      if (val === '__other__') {
        var ids = String(input.ids || '').replace(/[^0-9a-f,]/g, '');
        if (ids) { g.addQuery('practice', 'NOT IN', ids); }
        g.addNotNullQuery('practice');
      } else if (val === '__none__') { g.addNullQuery('practice'); }
      else if (/^[0-9a-f]{32}$/.test(val)) { g.addQuery('practice', val); }
      else { g.addQuery('sys_id', 'invalid'); }
    }
    else if (kind === 'band') { g.addQuery('score_band', val); g.addNotNullQuery('score'); }
    else if (kind === 'scored') { g.addNotNullQuery('score'); }
    else if (kind === 'active') { g.addQuery('state', 'IN', ACTIVE_STATES.join(',')); }
    else if (kind === 'completed') { g.addQuery('state', '3'); }
    else if (kind === 'age') {
      g.addQuery('state', 'IN', ACTIVE_STATES.join(','));
      var bi = parseInt(val, 10) || 0;
      jsFilter = function(r2) {
        var d = ageDays(r2);
        return bi === 0 ? d < 7 : (bi === 1 ? (d >= 7 && d < 14) : (bi === 2 ? (d >= 14 && d < 30) : d >= 30));
      };
    }
    /* kind 'total': no filter */
    g.orderByDesc('sys_updated_on');
    g.setLimit(500);
    g.query();
    while (g.next()) {
      if (jsFilter && !jsFilter(g)) { continue; }
      var st = String(g.getValue('state') || '1');
      var sc = parseFloat(g.getValue('score'));
      rows.push({
        id: g.getUniqueValue(),
        number: g.getValue('number'),
        title: String(g.getValue('short_description') || ''),
        practice: g.practice.getDisplayValue() || 'Unassigned',
        state: LABELS[st] || st,
        state_kind: KIND[st] || 'happy',
        score: isNaN(sc) ? null : Math.round(sc),
        age: ageDays(g),
        updated: g.getDisplayValue('sys_updated_on'),
        updated_ms: new GlideDateTime(g.getValue('sys_updated_on')).getNumericValue()
      });
    }
    data.drill = rows;
    return;
  }

  /* ---------- dashboard analytics ---------- */
  var counts = {}, total = 0, i;
  var ga = new GlideAggregate(TABLE);
  ga.addAggregate('COUNT');
  ga.groupBy('state');
  ga.query();
  while (ga.next()) {
    var n = parseInt(ga.getAggregate('COUNT'), 10) || 0;
    counts[String(ga.getValue('state'))] = n;
    total += n;
  }
  data.total = total;
  data.completed = counts['3'] || 0;
  var act = 0;
  for (i = 0; i < ACTIVE_STATES.length; i++) { act += counts[ACTIVE_STATES[i]] || 0; }
  data.active = act;

  var mx = 1;
  data.pipeline = [];
  for (i = 0; i < HAPPY.length; i++) {
    var c1 = counts[HAPPY[i]] || 0;
    if (c1 > mx) { mx = c1; }
    data.pipeline.push({state: HAPPY[i], label: LABELS[HAPPY[i]], count: c1, kind: 'happy'});
    /* On Hold (10): paused by PTAG but still open. Sits right after In Development,
       shown only when it holds records (same rule as the branches). */
    if (HAPPY[i] === '5' && counts['10']) {
      if (counts['10'] > mx) { mx = counts['10']; }
      data.pipeline.push({state: '10', label: LABELS['10'], count: counts['10'], kind: 'hold'});
    }
  }
  data.branches = [];
  for (i = 0; i < BRANCH.length; i++) {
    if (counts[BRANCH[i]]) {
      if (counts[BRANCH[i]] > mx) { mx = counts[BRANCH[i]]; }
      data.branches.push({state: BRANCH[i], label: LABELS[BRANCH[i]],
                          count: counts[BRANCH[i]], kind: KIND[BRANCH[i]]});
    }
  }
  data.maxCount = mx;

  var mix = [];
  var pr = new GlideAggregate(TABLE);
  pr.addAggregate('COUNT');
  pr.groupBy('practice');
  pr.query();
  while (pr.next()) {
    var plabel = '';
    try { plabel = String(pr.practice.getDisplayValue() || ''); } catch (e2) {}
    mix.push({label: plabel || 'Unassigned', id: String(pr.getValue('practice') || ''),
              count: parseInt(pr.getAggregate('COUNT'), 10) || 0});
  }
  mix.sort(function(a, b) { return b.count - a.count; });
  if (mix.length > 6) {
    var rest = 0;
    for (i = 5; i < mix.length; i++) { rest += mix[i].count; }
    mix = mix.slice(0, 5);
    mix.push({label: 'Other', id: '__other__', count: rest});
  }
  data.practiceMix = mix;

  var bands = [];
  var sb = new GlideAggregate(TABLE);
  sb.addNotNullQuery('score');
  sb.addAggregate('COUNT');
  sb.groupBy('score_band');
  sb.query();
  while (sb.next()) {
    var blabel = '';
    try { blabel = String(sb.score_band.getDisplayValue() || ''); } catch (e3) {}
    bands.push({label: blabel || 'No band', id: String(sb.getValue('score_band') || ''),
                count: parseInt(sb.getAggregate('COUNT'), 10) || 0});
  }
  bands.sort(function(a, b) { return b.count - a.count; });
  data.bands = bands;
  data.avgScore = null;
  data.scored = 0;
  var ssum = 0;
  var sgr = new GlideRecord(TABLE);
  sgr.addNotNullQuery('score');
  sgr.setLimit(5000);
  sgr.query();
  while (sgr.next()) {
    var sv = parseFloat(sgr.getValue('score'));
    if (!isNaN(sv)) { ssum += sv; data.scored++; }
  }
  if (data.scored) { data.avgScore = Math.round(ssum / data.scored); }

  var buckets = [0, 0, 0, 0];
  var oldest = null;
  var gr = new GlideRecord(TABLE);
  gr.addQuery('state', 'IN', ACTIVE_STATES.join(','));
  gr.setLimit(2000);
  gr.query();
  while (gr.next()) {
    var days = ageDays(gr);
    buckets[days < 7 ? 0 : (days < 14 ? 1 : (days < 30 ? 2 : 3))]++;
    if (!oldest || days > oldest.days) {
      oldest = {number: gr.getValue('number'), days: days,
                label: LABELS[String(gr.getValue('state'))] || ''};
    }
  }
  data.age = [{label: '< 7d', count: buckets[0], sev: 0},
              {label: '7-14d', count: buckets[1], sev: 1},
              {label: '14-30d', count: buckets[2], sev: 2},
              {label: '30d+', count: buckets[3], sev: 3}];
  data.oldest = oldest;

  /* ---------- Trends: REAL Performance Analytics daily scores ----------
     pa_scores_l1 totals (breakdown empty) for three PTAG indicators resolved BY
     NAME at runtime: pa_scores_l1.indicator holds pa_indicators.id, and that id
     differs per instance, so it is never hardcoded. start_at is 'YYYYMMDD' in the
     instance timezone. Window = the 90 days ending on the latest collected day.
     Nothing is fabricated: a day without a score row stays null (a gap), and an
     instance whose indicators have no scores yet reports 'empty' instead of a
     flat zero line. Cross-scope READ of pa_indicators / pa_scores_l1 from this
     scope rides sys_scope_privilege rows (runtime access tracking). */
  data.trends = (function() {
    var T = {state: 'empty', days: [], open: [], neu: [], avg: [], missing: [], points: 0};
    var WANT = {open: 'PTAG - Open requests', neu: 'PTAG - New requests',
                avg: 'PTAG - Average score of open requests'};
    try {
      var idOf = {}, keyOf = {}, key, ids = [];
      for (key in WANT) {
        var pi = new GlideRecord('pa_indicators');
        pi.addQuery('name', WANT[key]);
        pi.orderBy('sys_created_on');
        pi.setLimit(1);
        pi.query();
        if (pi.next() && pi.getValue('id')) {
          idOf[key] = String(pi.getValue('id'));
          keyOf[idOf[key]] = key;
          ids.push(idOf[key]);
        } else { T.missing.push(WANT[key]); }
      }
      if (T.missing.length) { T.state = 'missing'; return T; }
      var lastG = new GlideRecord('pa_scores_l1');
      lastG.addQuery('indicator', 'IN', ids.join(','));
      lastG.addNullQuery('breakdown');
      lastG.orderByDesc('start_at');
      lastG.setLimit(1);
      lastG.query();
      if (!lastG.next()) { return T; }
      var endKey = String(lastG.getValue('start_at'));
      var endMs = Date.UTC(parseInt(endKey.substr(0, 4), 10), parseInt(endKey.substr(4, 2), 10) - 1,
                           parseInt(endKey.substr(6, 2), 10));
      var DAYS = 90, at = {}, j;
      for (j = 0; j < DAYS; j++) {
        var dt = new Date(endMs - (DAYS - 1 - j) * 86400000);
        var dk = '' + dt.getUTCFullYear() + ('0' + (dt.getUTCMonth() + 1)).slice(-2) +
                 ('0' + dt.getUTCDate()).slice(-2);
        at[dk] = j;
        T.days.push(dk);
        T.open.push(null); T.neu.push(null); T.avg.push(null);
      }
      var sg = new GlideRecord('pa_scores_l1');
      sg.addQuery('indicator', 'IN', ids.join(','));
      sg.addNullQuery('breakdown');
      sg.addQuery('start_at', '>=', T.days[0]);
      sg.addQuery('start_at', '<=', endKey);
      sg.query();
      while (sg.next()) {
        var pos = at[String(sg.getValue('start_at'))];
        var ser = keyOf[String(sg.getValue('indicator'))];
        var val = parseFloat(sg.getValue('value'));
        if (pos === undefined || !ser || isNaN(val)) { continue; }
        T[ser][pos] = val;
        T.points++;
      }
      T.state = T.points ? 'ok' : 'empty';
    } catch (eT) {
      T.state = 'error';
      T.error = String(eT);
    }
    return T;
  })();
  data.asOf = new GlideDateTime().getDisplayValue();
})();
